+:root{font-family:'DM Sans',sans-serif;color:#f0eadc;--gold:#cfaa68;--muted:#b8b9a9;--panel:rgba(17,24,21,.8)}*{box-sizing:border-box}body{margin:0;background:#111713;overflow:hidden}#game,#scene{position:fixed;inset:0}#scene canvas{display:block;width:100%;height:100%;touch-action:none}.topbar{position:absolute;inset:0 0 auto;padding:24px 34px;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(180deg,rgba(8,14,12,.7),transparent);pointer-events:none}.brand{display:flex;align-items:center;gap:12px}.sigil{font-size:32px;color:#d9b66f;text-shadow:0 0 20px #e9c98566}.brand b{font:600 19px Cinzel;letter-spacing:.21em;display:block}.brand small{display:block;font:9px 'DM Sans';letter-spacing:.34em;color:#c4b89d;margin-top:3px}.location{font:10px 'DM Sans';letter-spacing:.2em;color:#e4ddcc}.location i{display:inline-block;width:7px;height:7px;background:#b9cf9a;border-radius:50%;box-shadow:0 0 12px #b9cf9a;margin-right:9px}.location span{color:#a9946e}.iconbtn{pointer-events:auto;color:#e4ddcc;background:#18201c99;border:1px solid #e8dfc33c;border-radius:50%;width:40px;height:40px;font-size:19px}.hud{position:absolute;top:105px;left:34px;display:flex;align-items:flex-start;gap:22px}.player-card{display:flex;align-items:center;gap:12px;padding:12px 16px 12px 11px;background:var(--panel);border:1px solid #e9dfbd24;border-radius:3px;min-width:240px;backdrop-filter:blur(10px)}.portrait{width:40px;height:40px;border:1px solid #c9a76b88;color:#d3b16e;display:grid;place-items:center;font-size:22px;background:linear-gradient(145deg,#485649,#19201b)}.vitals{flex:1}.vital-label{display:flex;justify-content:space-between;font-size:8px;letter-spacing:.12em;color:#c7c6b9;margin-bottom:4px}.vital-label b{font-size:9px;font-weight:500;color:#f0e7d1}.bar{height:4px;background:#ffffff19;width:100%}.bar i{display:block;height:100%;width:100%;background:linear-gradient(90deg,#a64438,#d88763);transition:width .2s}.stamina-label{margin:7px 0 4px}.stamina i{background:linear-gradient(90deg,#8a9d62,#c7d18a)}.quest{padding:10px 14px;border-left:1px solid #d2b57a;background:linear-gradient(90deg,#121914bd,transparent);display:grid;gap:4px}.quest-kicker{font-size:8px;color:#d7b977;letter-spacing:.18em}.quest b{font:500 14px Cinzel}.quest>span:last-child{font-size:10px;color:#c4c4b6}.compass{position:absolute;top:32px;left:50%;transform:translateX(-50%);display:flex;gap:15px;align-items:center;color:#eee5d2;font:10px Cinzel;letter-spacing:.15em}.compass-line{height:1px;width:86px;background:linear-gradient(90deg,transparent,#d4bd8e,transparent)}.compass-mark{color:#d7b977;font-size:13px}.bottom-left{position:absolute;bottom:26px;left:34px;display:flex;align-items:center;gap:18px}.weather{display:flex;align-items:center;gap:10px;padding:9px 12px;background:#111a17bd;border:1px solid #f2e9ce1b}.weather>span{font-size:20px;color:#d9bd7f}.weather b,.weather small{display:block}.weather b{font:14px Cinzel}.weather small{font-size:7px;letter-spacing:.12em;color:#c6c4b2;margin-top:3px}.coords{font-size:8px;letter-spacing:.14em;color:#e2ddcc}.bottom-right{position:absolute;right:34px;bottom:28px}.weapon{display:flex;align-items:center;gap:10px;background:#121a16c9;padding:9px 12px;border:1px solid #f2e9ce24}.weapon>span{font-size:21px;color:#d1b477}.weapon small,.weapon b{display:block}.weapon small{font-size:7px;letter-spacing:.16em;color:#c7bd9f}.weapon b{font:12px Cinzel;margin-top:3px}.weapon kbd{margin-left:12px;border:1px solid #ddd0aa55;padding:3px 6px;font-size:9px;color:#d9ca9f}.toast{position:absolute;left:50%;top:25%;transform:translate(-50%,-8px);opacity:0;transition:.3s;background:#121a16db;border:1px solid #d3b87966;padding:11px 19px;font:12px Cinzel;letter-spacing:.07em;color:#eee2c4;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.interact-hint{position:absolute;left:50%;top:54%;transform:translate(-50%,-50%);padding:8px 14px;border:1px solid #e5d4a65c;background:#101714ba;font-size:9px;letter-spacing:.16em;opacity:0;transition:.2s}.interact-hint.show{opacity:1}.modal{position:absolute;inset:0;display:grid;place-items:center;background:#07100dcc;backdrop-filter:blur(7px)}.modal.hidden{display:none}.modal-card{position:relative;width:min(480px,90vw);padding:36px;background:#17201beF;border:1px solid #ccb27266;box-shadow:0 24px 100px #0008}.close{position:absolute;right:16px;top:13px;background:none;border:0;color:#eee;font-size:24px}.eyebrow{font-size:9px;letter-spacing:.22em;color:#d5b876}.modal h1{font:500 28px Cinzel;margin:12px 0}.modal p{font-size:13px;line-height:1.7;color:#c6c5b8}.menu-grid{display:grid;gap:8px;margin-top:24px}.menu-grid button{text-align:left;border:1px solid #e0d4b326;padding:12px 14px;background:#ffffff07;color:#e7dfca;font:11px Cinzel;letter-spacing:.08em}.menu-grid button small{float:right;color:#afa995;font:10px 'DM Sans';letter-spacing:0}.touch-actions,.stick,.look-zone{display:none}
+@media(max-width:700px){.topbar{padding:calc(env(safe-area-inset-top) + 13px) 16px 12px}.brand{gap:8px}.sigil{font-size:25px}.brand b{font-size:14px}.brand small{font-size:7px}.location{font-size:8px;letter-spacing:.08em}.iconbtn{width:34px;height:34px}.compass{top:72px}.hud{top:105px;left:12px;gap:8px;flex-direction:column}.player-card{min-width:190px;padding:8px 10px}.portrait{width:31px;height:31px}.quest{padding:6px 9px;max-width:185px}.quest b{font-size:11px}.quest>span:last-child{font-size:8px}.bottom-left{bottom:calc(env(safe-area-inset-bottom) + 14px);left:12px;gap:8px}.weather{padding:6px 8px}.coords{font-size:7px}.bottom-right{right:10px;bottom:calc(env(safe-area-inset-bottom) + 14px)}.weapon{padding:6px 8px;gap:7px}.weapon b{font-size:10px}.weapon kbd{display:none}.touch-actions{position:absolute;display:block;right:15px;bottom:calc(env(safe-area-inset-bottom) + 74px);width:156px;height:170px;pointer-events:none}.action{pointer-events:auto;position:absolute;border-radius:50%;border:1px solid #e1d3ac66;background:#131b18c9;color:#eee3cb;width:47px;height:47px;display:grid;place-content:center;box-shadow:0 4px 16px #0004;touch-action:none}.action span{font-size:17px;line-height:18px}.action small{font-size:6px;letter-spacing:.08em}.attack{right:0;top:58px;width:57px;height:57px;border-color:#d899796e}.jump{right:50px;top:0}.guard{right:0;top:0}.dodge{right:59px;top:100px;width:43px;height:43px}.interact{right:108px;top:53px;width:40px;height:40px}.stick{display:block;position:absolute;left:20px;bottom:calc(env(safe-area-inset-bottom) + 38px);width:132px;height:132px;touch-action:none}.stick-ring{position:absolute;inset:12px;border:1px solid #dfd5b238;border-radius:50%;background:#121a1680;backdrop-filter:blur(4px)}#stickKnob{position:absolute;width:48px;height:48px;border-radius:50%;left:50%;top:50%;transform:translate(-50%,-50%);border:1px solid #eee0b878;background:#a2946d65;box-shadow:0 2px 12px #0005}.look-zone{display:block;position:absolute;right:0;top:35%;width:46%;height:35%;touch-action:none;pointer-events:auto}.look-zone span{position:absolute;right:18px;top:50%;font-size:7px;letter-spacing:.12em;color:#ffffff32}.interact-hint{top:47%;font-size:8px}.toast{top:34%;font-size:10px}.modal-card{padding:27px 22px}.weather small{font-size:6px}}
+@media(orientation:landscape) and (max-height:500px){.topbar{padding:10px 18px}.compass{top:12px}.hud{top:63px;left:15px;flex-direction:row}.player-card{min-width:175px;padding:6px 8px}.portrait{width:28px;height:28px}.quest{max-width:175px}.touch-actions{right:14px;bottom:15px;transform:scale(.8);transform-origin:right bottom}.stick{left:18px;bottom:15px;width:112px;height:112px}.bottom-left{left:14px;bottom:10px}.weather{display:none}.bottom-right{bottom:10px}.look-zone{top:18%;height:53%}}

