+import * as THREE from 'three';
+
+const sceneRoot=document.querySelector('#scene');
+const scene=new THREE.Scene();scene.background=new THREE.Color('#91a89b');scene.fog=new THREE.FogExp2('#9aa99b',.012);
+const camera=new THREE.PerspectiveCamera(48,innerWidth/innerHeight,.1,220);
+const renderer=new THREE.WebGLRenderer({antialias:innerWidth>700,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,innerWidth<700?1.35:1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=innerWidth>700;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.08;sceneRoot.appendChild(renderer.domElement);
+const hemi=new THREE.HemisphereLight(0xd6e4df,0x514a38,2);scene.add(hemi);const sun=new THREE.DirectionalLight(0xffe6bd,3.4);sun.position.set(-35,52,24);sun.castShadow=innerWidth>700;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-38;sun.shadow.camera.right=38;sun.shadow.camera.top=38;sun.shadow.camera.bottom=-38;sun.shadow.bias=-.00025;scene.add(sun);scene.add(sun.target);
+const mat=(color,roughness=.85,metalness=0)=>new THREE.MeshStandardMaterial({color,roughness,metalness});
+const groundMat=mat('#66765a'),bark=mat('#554539'),leafMats=['#405d45','#536d49','#637750','#385445'].map(c=>mat(c)),stone=mat('#77776a'),stoneLight=mat('#969382'),roofMat=mat('#59473a'),cloth=mat('#8c6544'),darkCloth=mat('#35423c'),leather=mat('#47352a'),iron=mat('#758078',.34,.72),skin=mat('#d0a67d'),gold=mat('#be995b',.35,.65);
+const rand=(()=>{let s=812734;return()=>((s=(s*1664525+1013904223)>>>0)/4294967296)})();
+function terrainHeight(x,z){return .28*Math.sin(x*.21+z*.13)+.42*Math.cos(z*.19-x*.11)+.20*Math.sin(x*.48)*Math.cos(z*.35)+Math.max(0,Math.hypot(x+30,z+38)-27)*.36}
+const size=170,segments=120,verts=[],colors=[],indices=[];for(let j=0;j<=segments;j++)for(let i=0;i<=segments;i++){let x=(i/segments-.5)*size,z=(j/segments-.5)*size,y=terrainHeight(x,z);verts.push(x,y,z);let shade=.91+rand()*.16;colors.push(.37*shade,.43*shade,.31*shade)}for(let j=0;j<segments;j++)for(let i=0;i<segments;i++){let a=j*(segments+1)+i,b=a+segments+1;indices.push(a,b,a+1,b,b+1,a+1)}const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(verts,3));geo.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));geo.setIndex(indices);geo.computeVertexNormals();let ground=new THREE.Mesh(geo,new THREE.MeshStandardMaterial({vertexColors:true,roughness:1}));ground.receiveShadow=true;scene.add(ground);
+// A curving, translucent alpine stream with soft animated surface ripples.
+const riverMat=new THREE.MeshPhysicalMaterial({color:'#638f8d',roughness:.22,metalness:.12,transparent:true,opacity:.79,clearcoat:.8,clearcoatRoughness:.15,side:THREE.DoubleSide});let riverGeo=new THREE.BufferGeometry(),rv=[],ri=[];for(let k=0;k<=110;k++){let z=-62+k*1.15,x=Math.sin(z*.075)*8+2;for(let side of [-1,1]){rv.push(x+side*2.3,terrainHeight(x,z)+.10,z)}}for(let k=0;k<110;k++){let a=k*2;ri.push(a,a+2,a+1,a+1,a+2,a+3)}riverGeo.setAttribute('position',new THREE.Float32BufferAttribute(rv,3));riverGeo.setIndex(ri);riverGeo.computeVertexNormals();const river=new THREE.Mesh(riverGeo,riverMat);scene.add(river);
+const waterRipples=[];for(let i=0;i<46;i++){let z=-58+rand()*112,x=Math.sin(z*.075)*8+2+(rand()-.5)*3;let m=new THREE.Mesh(new THREE.RingGeometry(.07,.12,12),new THREE.MeshBasicMaterial({color:'#d6ded0',transparent:true,opacity:.25,side:THREE.DoubleSide}));m.rotation.x=-Math.PI/2;m.position.set(x,terrainHeight(x,z)+.13,z);scene.add(m);waterRipples.push(m)}
+function addTree(x,z,scale=1,type=0){let y=terrainHeight(x,z),g=new THREE.Group();g.position.set(x,y,z);g.scale.setScalar(scale);let trunk=new THREE.Mesh(new THREE.CylinderGeometry(.18,.35,3.6,7),bark);trunk.position.y=1.8;trunk.castShadow=true;g.add(trunk);if(type===2){for(let n=0;n<4;n++){let branch=new THREE.Mesh(new THREE.ConeGeometry(1.55-n*.22,2.2,7),leafMats[(n+type)%4]);branch.position.set(0,2.8+n*.67,0);branch.scale.z=.85;branch.castShadow=true;branch.receiveShadow=true;g.add(branch)}}else{for(let n=0;n<5;n++){let l=new THREE.Mesh(new THREE.IcosahedronGeometry(1.02+rand()*.32,1),leafMats[(n+type)%4]);let a=n*2.4;l.position.set(Math.cos(a)*.52,3.3+(n%3)*.56,Math.sin(a)*.52);l.scale.set(1.2,.9,1.1);l.castShadow=true;g.add(l)}}scene.add(g);return g}
+for(let i=0;i<300;i++){let x=(rand()-.5)*118,z=(rand()-.5)*120;if(Math.abs(x-(Math.sin(z*.075)*8+2))<7||Math.hypot(x-5,z-2)<10||Math.hypot(x+11,z-16)<8)continue;addTree(x,z,.72+rand()*.8,Math.floor(rand()*3))}
+for(let i=0;i<115;i++){let x=(rand()-.5)*88,z=(rand()-.5)*90;if(Math.abs(x-(Math.sin(z*.075)*8+2))<6)continue;let r=.14+rand()*.35;let m=new THREE.Mesh(new THREE.DodecahedronGeometry(r,1),i%5?mat('#747667'):mat('#596850'));m.position.set(x,terrainHeight(x,z)+r*.6,z);m.rotation.set(rand()*2,rand()*2,rand()*2);m.castShadow=true;m.receiveShadow=true;scene.add(m)}
+// Distant mountain silhouettes create layered depth behind the explorable vale.
+for(let i=0;i<13;i++){let x=-76+i*13,z=-65-(i%3)*7,h=18+rand()*23;let m=new THREE.Mesh(new THREE.ConeGeometry(9+rand()*6,h,7),mat(i%2?'#6d8178':'#7e9082'));m.position.set(x,terrainHeight(x,z)+h*.42,z);m.rotation.y=rand()*2;m.castShadow=true;scene.add(m)}
+// Ruined watchtower: faceted masonry, broken crown, doorway, and a glowing beacon.
+function buildTower(x,z){let g=new THREE.Group();g.position.set(x,terrainHeight(x,z),z);let base=new THREE.Mesh(new THREE.CylinderGeometry(4.2,4.8,10,12),stone);base.position.y=5;base.castShadow=true;base.receiveShadow=true;g.add(base);for(let i=0;i<12;i++){let a=i*Math.PI/6;let crenel=new THREE.Mesh(new THREE.BoxGeometry(1.05,1.3,1),stoneLight);crenel.position.set(Math.cos(a)*3.65,10.55,Math.sin(a)*3.65);crenel.rotation.y=-a;g.add(crenel)}let door=new THREE.Mesh(new THREE.BoxGeometry(1.55,3,0.5),mat('#292c26'));door.position.set(0,1.5,4.4);g.add(door);let glow=new THREE.PointLight(0xffbe70,4,18);glow.position.set(0,9,0);g.add(glow);let flame=new THREE.Mesh(new THREE.OctahedronGeometry(.38),new THREE.MeshBasicMaterial({color:'#ffd28a'}));flame.position.set(0,9,0);g.add(flame);scene.add(g)}buildTower(-11,17);
+// A little weather-worn settlement and distant keep marks the far ridge.
+function buildHouse(x,z,s=1){let g=new THREE.Group();g.position.set(x,terrainHeight(x,z),z);const walls=new THREE.Mesh(new THREE.BoxGeometry(5*s,3.5*s,4*s),mat('#8a806b'));walls.position.y=1.75*s;walls.castShadow=true;walls.receiveShadow=true;g.add(walls);const roof=new THREE.Mesh(new THREE.ConeGeometry(3.9*s,2.8*s,4),roofMat);roof.position.y=4.65*s;roof.rotation.y=Math.PI/4;roof.castShadow=true;g.add(roof);const d=new THREE.Mesh(new THREE.BoxGeometry(.9*s,1.8*s,.2*s),leather);d.position.set(0,.9*s,2.05*s);g.add(d);scene.add(g)}buildHouse(16,9);buildHouse(21,14,.8);buildHouse(13,16,.72);
+// Interactive stone footbridge over the stream.
+const bridge=new THREE.Group();{let z=-9,x=Math.sin(z*.075)*8+2;for(let i=-3;i<=3;i++){let slab=new THREE.Mesh(new THREE.BoxGeometry(1.18,.45,5.3),stoneLight);slab.position.set(x+i*1.06,terrainHeight(x,z)+1.05-Math.abs(i)*.12,z);slab.rotation.z=(i<0?1:-1)*.09;slab.castShadow=true;slab.receiveShadow=true;bridge.add(slab)}bridge.userData.interact=true;bridge.position.set(0,0,0);scene.add(bridge)}
+// New articulated wayfarer model: distinct head, layered torso, limbs, gloves, boots and carried steel.
+const player=new THREE.Group();scene.add(player);player.position.set(5,terrainHeight(5,2),2);const rig=new THREE.Group();player.add(rig);
+function ell(parent,material,x,y,z,sx,sy,sz,seg=14){let m=new THREE.Mesh(new THREE.SphereGeometry(1,seg,Math.max(8,seg-2)),material);m.position.set(x,y,z);m.scale.set(sx,sy,sz);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
+function capsule(parent,r,len,material){let m=new THREE.Mesh(new THREE.CapsuleGeometry(r,len,4,8),material);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
+// Legs articulated around upper-leg pivots; separate greaves and boots add readable anatomy.
+const legs=[];for(let side of [-1,1]){let leg=new THREE.Group();leg.position.set(side*.25,.91,0);rig.add(leg);let thigh=capsule(leg,.16,.43,darkCloth);thigh.position.y=-.24;let knee=ell(leg,leather,0,-.49,0,.17,.17,.17);let shin=capsule(leg,.125,.34,iron);shin.position.set(0,-.7,.015);let boot=new THREE.Mesh(new THREE.BoxGeometry(.29,.19,.43),leather);boot.position.set(0,-.99,-.075);boot.castShadow=true;leg.add(boot);let strap=new THREE.Mesh(new THREE.TorusGeometry(.132,.028,6,12),gold);strap.rotation.x=Math.PI/2;strap.position.set(0,-.63,0);leg.add(strap);legs.push(leg)}
+// torso and articulated arm pivots
+ell(rig,darkCloth,0,1.25,0,.42,.52,.26);ell(rig,cloth,0,1.52,0,.44,.36,.275);let chest=new THREE.Mesh(new THREE.BoxGeometry(.49,.5,.065),iron);chest.position.set(0,1.57,-.245);chest.rotation.x=-.08;rig.add(chest);for(let side of [-1,1]){let strap=new THREE.Mesh(new THREE.BoxGeometry(.09,.72,.07),leather);strap.position.set(side*.2,1.35,-.25);strap.rotation.z=side*.28;rig.add(strap);let pauldron=ell(rig,gold,side*.4,1.75,0,.24,.15,.24);pauldron.rotation.z=side*-.22}
+// head, ears, hair and practical travel hood
+ell(rig,skin,0,2.18,0,.23,.29,.22);ell(rig,mat('#433329'),0,2.39,.015,.245,.15,.23);ell(rig,mat('#493829'),0,2.23,-.18,.24,.25,.13);for(let side of [-1,1])ell(rig,skin,side*.235,2.19,0,.055,.09,.055);
+const arms=[];for(let side of [-1,1]){let arm=new THREE.Group();arm.position.set(side*.48,1.67,0);rig.add(arm);let upper=capsule(arm,.135,.35,cloth);upper.position.y=-.26;let sleeve=capsule(arm,.145,.23,darkCloth);sleeve.position.y=-.52;let fore=capsule(arm,.105,.34,iron);fore.position.y=-.76;ell(arm,leather,0,-.99,-.005,.12,.13,.1);let hand=ell(arm,skin,0,-1.02,-.04,.105,.1,.09);arms.push(arm)}
+let sword=new THREE.Group();const blade=new THREE.Mesh(new THREE.BoxGeometry(.095,1.2,.04),iron);blade.position.y=-.56;sword.add(blade);let tip=new THREE.Mesh(new THREE.ConeGeometry(.067,.2,4),iron);tip.position.y=-1.25;sword.add(tip);let cross=new THREE.Mesh(new THREE.BoxGeometry(.36,.09,.13),gold);cross.position.y=.06;sword.add(cross);let grip=new THREE.Mesh(new THREE.CylinderGeometry(.055,.065,.33,8),leather);grip.position.y=.27;sword.add(grip);sword.position.set(.57,.67,.05);sword.rotation.z=-.12;rig.add(sword);
+// distant mossy ruins and a quest waystone
+for(let i=0;i<9;i++){let x=-24+i*2.2,z=29+Math.sin(i*.8)*2;let p=new THREE.Mesh(new THREE.BoxGeometry(1.4,2.2+rand()*2,1.4),stone);p.position.set(x,terrainHeight(x,z)+1,z);p.rotation.y=rand();p.castShadow=true;scene.add(p)}
